-- Database e-commerce SINTETIS: skema + data (8 tabel). Impor lewat phpMyAdmin (tab Import) atau: mysql -u root < database.sql
-- Target: MySQL 8 / MariaDB 10.2+ (XAMPP). Data dibuat acak, bukan data bisnis nyata.

SET NAMES utf8mb4;
SET autocommit = 0;


DROP DATABASE IF EXISTS ecommerce_sql;
CREATE DATABASE ecommerce_sql CHARACTER SET utf8mb4;   -- collation default; jalan di MySQL 8 dan MariaDB (XAMPP)
USE ecommerce_sql;

CREATE TABLE customers (
    customer_id         INT          NOT NULL,
    city                VARCHAR(50)  NOT NULL,
    province            VARCHAR(50)  NOT NULL,
    signup_date         DATE         NOT NULL,
    acquisition_channel VARCHAR(20)  NOT NULL,   -- organic | ads | referral | marketplace
    PRIMARY KEY (customer_id),
    KEY idx_cust_signup (signup_date)
) ENGINE=InnoDB;

CREATE TABLE sellers (
    seller_id   INT          NOT NULL,
    seller_name VARCHAR(50)  NOT NULL,
    city        VARCHAR(50)  NOT NULL,
    province    VARCHAR(50)  NOT NULL,
    join_date   DATE         NOT NULL,
    PRIMARY KEY (seller_id)
) ENGINE=InnoDB;

CREATE TABLE categories (
    category_id   INT         NOT NULL,
    category_name VARCHAR(50) NOT NULL,
    PRIMARY KEY (category_id)
) ENGINE=InnoDB;

CREATE TABLE products (
    product_id   INT           NOT NULL,
    category_id  INT           NOT NULL,
    seller_id    INT           NOT NULL,
    product_name VARCHAR(100)  NOT NULL,
    price        DECIMAL(12,2) NOT NULL,         -- Rupiah
    weight_g     INT           NOT NULL,
    PRIMARY KEY (product_id),
    KEY idx_prod_cat (category_id),
    KEY idx_prod_seller (seller_id),
    CONSTRAINT fk_prod_cat    FOREIGN KEY (category_id) REFERENCES categories (category_id),
    CONSTRAINT fk_prod_seller FOREIGN KEY (seller_id)   REFERENCES sellers (seller_id)
) ENGINE=InnoDB;

CREATE TABLE orders (
    order_id                INT         NOT NULL,
    customer_id             INT         NOT NULL,
    order_status            VARCHAR(20) NOT NULL,   -- delivered | returned | canceled
    order_purchase_ts       DATETIME    NOT NULL,
    order_shipped_ts        DATETIME    NULL,       -- NULL jika canceled
    order_delivered_ts      DATETIME    NULL,       -- NULL jika canceled
    estimated_delivery_date DATE        NOT NULL,
    PRIMARY KEY (order_id),
    KEY idx_ord_cust (customer_id),
    KEY idx_ord_purchase (order_purchase_ts),
    CONSTRAINT fk_ord_cust FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
) ENGINE=InnoDB;

CREATE TABLE order_items (
    order_item_id INT           NOT NULL,
    order_id      INT           NOT NULL,
    item_seq      INT           NOT NULL,           -- urutan item dalam pesanan
    product_id    INT           NOT NULL,
    seller_id     INT           NOT NULL,
    unit_price    DECIMAL(12,2) NOT NULL,           -- harga saat transaksi
    quantity      INT           NOT NULL,
    freight_value DECIMAL(12,2) NOT NULL,           -- ongkir per item
    PRIMARY KEY (order_item_id),
    KEY idx_item_order (order_id),
    KEY idx_item_product (product_id),
    KEY idx_item_seller (seller_id),
    CONSTRAINT fk_item_order   FOREIGN KEY (order_id)   REFERENCES orders (order_id),
    CONSTRAINT fk_item_product FOREIGN KEY (product_id) REFERENCES products (product_id),
    CONSTRAINT fk_item_seller  FOREIGN KEY (seller_id)  REFERENCES sellers (seller_id)
) ENGINE=InnoDB;

CREATE TABLE payments (
    payment_id    INT           NOT NULL,
    order_id      INT           NOT NULL,
    payment_seq   INT           NOT NULL,             -- 1 atau 2 jika dibayar terpisah
    payment_type  VARCHAR(20)   NOT NULL,             -- credit_card | bank_transfer | ewallet | cod
    installments  INT           NOT NULL,
    payment_value DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (payment_id),
    KEY idx_pay_order (order_id),
    CONSTRAINT fk_pay_order FOREIGN KEY (order_id) REFERENCES orders (order_id)
) ENGINE=InnoDB;

CREATE TABLE reviews (
    review_id    INT  NOT NULL,
    order_id     INT  NOT NULL,
    review_score TINYINT NOT NULL,                    -- 1..5
    review_date  DATE NOT NULL,
    PRIMARY KEY (review_id),
    KEY idx_rev_order (order_id),
    CONSTRAINT fk_rev_order FOREIGN KEY (order_id) REFERENCES orders (order_id),
    CONSTRAINT chk_score CHECK (review_score BETWEEN 1 AND 5)
) ENGINE=InnoDB;









COMMIT;
